mapper.select:
SELECT COUNT(*)
FROM posts p
WHERE p.status = 'normal'

    AND p.created_at >= #{since}


    AND EXISTS (
        SELECT 1 FROM post_tags pt
        WHERE pt.post_id = p.id AND pt.tag_id = #{tagId}
    )


    AND EXISTS (
        SELECT 1 FROM post_files pf
        WHERE pf.post_id = p.id AND pf.source = #{source}
    )
